/**
 * plugin-command-adapter.ts —— Maps accepted plugin commands to RegisteredCommand.
 *
 * - ID fixed as ext.plugin.<pluginId>.<contributionKey>
 * - Icon, effect, requiresPermission, when, execute all generated by host catalogs
 * - Plugin data only used as restricted display input
 * - Execute wrapper re-validates registry owner/revision, trusted scope,
 *   effective eligibility, RBAC/Policy visibility, route context, action availability
 */

import type { RegisteredCommand, CommandContext, CommandEffect } from './types'
import type { PluginUiCommandAcceptedCommand } from '@aiproj/types'
import { useCommandRegistryStore } from './store'
import {
  resolvePluginIcon,
  resolvePluginAction,
  validateActionParams,
} from './plugin-host-catalogs'

/**
 * Convert an accepted plugin command to a RegisteredCommand.
 * All security-sensitive fields (icon, effect, execute, requiresPermission, when)
 * are generated by host catalogs, not plugin data.
 */
export function adaptPluginCommand(
  accepted: PluginUiCommandAcceptedCommand,
  /** Current trusted scope for validation. */
  currentScope: {
    organizationId: string
    projectId?: string
  },
): RegisteredCommand {
  const actionEntry = resolvePluginAction(accepted.actionKey)
  const icon = resolvePluginIcon(accepted.iconKey)
  // 写入型入口（open-plugin-action-preview）在 RegisteredCommand 层映射为确认类副作用：
  // 只打开宿主生成的 action preview，不等同于提交；核心 CommandEffect 词表不变。
  const effect: CommandEffect =
    actionEntry?.kind === 'open-plugin-action-preview'
      ? 'open-confirm'
      : ((actionEntry?.kind ?? 'navigate') as CommandEffect)

  return {
    id: accepted.id,
    label: accepted.label,
    keywords: accepted.keywords.length > 0 ? accepted.keywords : undefined,
    icon,
    group: 'plugin',
    effect,
    requiresPermission:
      accepted.requiredPermissions.length > 0 ? accepted.requiredPermissions : undefined,
    when: (_ctx: CommandContext) => {
      // Scope validation: contribution's scopeKind must match current context
      if (accepted.scopeKind === 'project' && !currentScope.projectId) {
        return false
      }
      // Route context validation (if specified)
      if (accepted.routeContextKey) {
        // TODO: Route context predicate validation (task 6.1)
        // For now, always return true for route context
      }
      return true
    },
    execute: (_ctx: CommandContext) => {
      // Execute wrapper: re-validate before calling host handler
      const store = useCommandRegistryStore.getState()

      // 1. Check command still exists in registry
      const currentCmd = store.commands.get(accepted.id)
      if (!currentCmd) {
        console.warn(`[plugin-command] Command ${accepted.id} no longer in registry`)
        return
      }

      // 2. Check owner metadata still valid
      const meta = store.ownerMeta.get(accepted.id)
      if (!meta || meta.ownerKey !== accepted.pluginId) {
        console.warn(`[plugin-command] Owner mismatch for ${accepted.id}`)
        return
      }

      // 3. Check revision still matches
      if (meta.revision !== accepted.instanceRevision) {
        console.warn(`[plugin-command] Revision mismatch for ${accepted.id}`)
        return
      }

      // 4. Validate action params
      const paramErrors = validateActionParams(accepted.actionKey, accepted.actionParams)
      if (paramErrors.length > 0) {
        console.warn(`[plugin-command] Action param validation failed: ${paramErrors.join(', ')}`)
        return
      }

      // 5. Call host handler (safe navigation/form/confirm/preview only)。
      // 故障隔离：单个插件命令执行失败只影响自身，不影响核心命令（spec Requirement 6）。
      try {
        if (accepted.actionKey === 'navigate') {
          const route = accepted.actionParams.route
          if (route) {
            // Replace :projectId placeholder with actual project ID
            const resolvedRoute = route.replace(':projectId', currentScope.projectId ?? '')
            // Use Next.js router for navigation
            if (typeof window !== 'undefined') {
              window.location.href = resolvedRoute
            }
          }
        } else if (accepted.actionKey === 'open-form') {
          // TODO: Open form dialog (task 6.1)
          console.log(`[plugin-command] Open form: ${accepted.actionParams.formId}`)
        } else if (accepted.actionKey === 'open-confirm') {
          // TODO: Open confirm dialog (task 6.1)
          console.log(`[plugin-command] Open confirm: ${accepted.actionParams.confirmId}`)
        } else if (accepted.actionKey === 'open-plugin-action-preview') {
          // 宿主持有的预览接缝：只派发宿主可重解析的稳定引用，
          // 由宿主生成 action preview；preview ≠ 提交，正式写入必须经统一确认边界
          // （v3-plugin-action-preview-boundary 接管消费）。
          if (typeof window !== 'undefined') {
            window.dispatchEvent(
              new CustomEvent('aiproj:plugin-action-preview', {
                detail: {
                  actionRef: accepted.actionParams.actionRef ?? '',
                  pluginId: accepted.pluginId,
                  contributionKey: accepted.contributionKey,
                  instanceRevision: accepted.instanceRevision,
                },
              }),
            )
          }
        }
      } catch (error) {
        console.warn(`[plugin-command] Execute failed for ${accepted.id}:`, error)
      }
    },
  }
}

/**
 * Adapt multiple accepted commands to RegisteredCommand[].
 * Stable sorting by contribution key within plugin.
 */
export function adaptPluginCommands(
  accepted: PluginUiCommandAcceptedCommand[],
  currentScope: {
    organizationId: string
    projectId?: string
  },
): RegisteredCommand[] {
  return accepted
    .slice()
    .sort((a, b) => a.contributionKey.localeCompare(b.contributionKey))
    .map((cmd) => adaptPluginCommand(cmd, currentScope))
}
